import itertools,json
from pathlib import Path
from unittest.mock import patch
import pytest
from lupa.lua54 import LuaRuntime
from tools.script_recovery.convert_quest_unit import UnitConverter
from tools.script_recovery.build_readable_unit import readable_file
ROOT=Path(__file__).resolve().parents[2]
@pytest.fixture(scope='module')
def wife(tmp_path_factory):
 unit=json.loads((ROOT/'refs/script_recovery/heros_old_house/units/Q_HerosOldHouse.json').read_text())
 c=UnitConverter(ROOT/'refs/script_recovery/heros_old_house/translation_unit_typed.json')
 out=tmp_path_factory.mktemp('wife-cycle')
 with patch.object(c,'constructor_defaults',return_value={}):c.convert(unit,out)
 draft=(out/'FSE/HerosOldHouse/Entities/FishermansWife.lua').read_text()
 return draft,readable_file(draft)[0]
HARNESS="return function(delay, moveDelay, hit, limit, marker)\n local frames,polls,speech,moves,fades=0,0,0,0,0\n local task,remaining='',0\n local events={}\n local actor={}\n function actor:GetAngleXY()return 0 end\n function actor:IsTalkedToByHero()polls=polls+1;return false end\n function actor:MsgIsHitByHero()return hit and polls==1 end\n function actor:MsgIsHitByAnySpecialAbilityFromHero()return false end\n function actor:Speak(hero,line,a,b,c,d)\n  assert(hero==actor and line=='TEXT_QST_032_FISHERWIFE_ATTACKED')\n  speech=speech+1;task='speech';remaining=delay\n end\n function actor:IsPerformingScriptTask()\n  if remaining>0 then remaining=remaining-1;return true end\n  return false\n end\n function actor:MoveToPosition(pos,speed,kind,a,b)\n  assert(pos and pos.x==(marker and 7 or 0) and pos.y==(marker and 8 or 0) and pos.z==(marker and 9 or 0) and speed==3 and kind==1 and a==false and b==true)\n  moves=moves+1;task='move';remaining=moveDelay\n end\n local resource={}\n function resource:NewResource()return 40 end\n function resource:PrepareResource(id)assert(id==40)end\n function resource:TryAcquire(id,who,flags)assert(id==40 and who==actor and flags==4);return true end\n function resource:ScriptThing(id)assert(id==40);return actor end\n function resource:ReleaseResource(id)assert(id==40);events[#events+1]='release' end\n function resource:StartMovie(name)assert(name=='');events[#events+1]='start';return 50 end\n function resource:DestroyMovie(id)assert(id==50);events[#events+1]='destroy' end\n local q={}\n function q:RetailResources()return resource end\n function q:NewScriptFrame(who)assert(who==actor);frames=frames+1;assert(frames<=limit+1);return frames<limit end\n function q:IsActiveThreadTerminating()return frames>=limit end\n function q:EntitySetAsKillable(who,a,b)assert(who==actor and b==true);events[#events+1]='killable:'..tostring(a)end\n function q:SetIsPushableByHero(who,value)assert(who==actor and value==false)end\n function q:GetThingWithScriptName(name)assert(name=='HiddenBooty' or name=='FisherWifeLeaveMarker');return marker and name=='FisherWifeLeaveMarker' and {IsNull=function()return false end,GetPos=function()return{x=7,y=8,z=9}end} or nil end\n function q:RegisterTimer()events[#events+1]='register';return 60 end\n function q:SetTimer(id,value)assert(id==60 and value==5)end\n function q:GetTimer(id)assert(id==60);return 100 end\n function q:DeregisterTimer(id)assert(id==60);events[#events+1]='deregister' end\n function q:GetStateBool(name)return false end\n function q:SetStateBool(name,value)assert(value and (name=='WifeAttacked' or name=='WifeAttackedAndLeft'));events[#events+1]=name end\n function q:SetThingHasInformation(who,a,b,c)assert(who==actor and not a and not b and not c)end\n function q:PauseAllNonScriptedEntities(value)events[#events+1]='pause:'..tostring(value)end\n function q:GetHealth(who)assert(who==actor);return 100 end\n function q:GetHero()return actor end\n function q:FadeOutAndKillEntity(who,a,b,c)assert(who==actor and a and b==1 and c);fades=fades+1 end\n setmetatable(q,{__index=function(_,name)return function()error('unexpected '..name)end end})\n Init(q,actor)\n debug.sethook(function()error('instruction budget')end,'',100000)\n Main(q,actor)\n debug.sethook()\n assert(frames==limit,'frames '..frames..' expected '..limit)\n assert(polls>1,'polling stopped after attack')\n assert(speech==(hit and 1 or 0) and moves==speech and fades==speech)\n assert(events[#events]=='release' and events[#events-1]=='deregister','resource lifetime')\n return frames..':'..polls..':'..table.concat(events,',')\nend"

@pytest.mark.parametrize('style',[0,1])
@pytest.mark.parametrize('delay,move_delay,hit,limit,marker',list(itertools.product((0,1,3),(0,1,2),(False,True),(12,17),(False,True))))
def test_actual_wife_resumes_polling_after_attack_speech(wife,style,delay,move_delay,hit,limit,marker):
 lua=LuaRuntime();lua.execute(wife[style]);check=lua.execute(HARNESS)
 assert check(delay,move_delay,hit,limit,marker)
